// ServerInterface represents all server handlers.
type ServerInterface interface {
	// Sign in as the administrator
	// (POST /admin/login)
	AdminLogin(w http.ResponseWriter, r *http.Request)
	// End this administrator session
	// (POST /admin/logout)
	AdminLogout(w http.ResponseWriter, r *http.Request, params AdminLogoutParams)
	// Set a new administrator password; other admin sessions end
	// (POST /admin/password)
	ChangeAdminPassword(w http.ResponseWriter, r *http.Request, params ChangeAdminPasswordParams)
	// The server settings an administrator can change
	// (GET /admin/settings)
	GetAdminSettings(w http.ResponseWriter, r *http.Request, params GetAdminSettingsParams)
	// Change server settings
	// (PUT /admin/settings)
	UpdateAdminSettings(w http.ResponseWriter, r *http.Request, params UpdateAdminSettingsParams)
	// Set the administrator password, once, on a new server
	// (POST /admin/setup)
	AdminSetup(w http.ResponseWriter, r *http.Request)
	// The invitation behind an invitation link
	// (GET /auth/invites/{inviteToken})
	GetInvite(w http.ResponseWriter, r *http.Request, inviteToken string)
	// Sign in with email and password (accounts mode)
	// (POST /auth/login)
	Login(w http.ResponseWriter, r *http.Request)
	// End this session
	// (POST /auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// Trade the code the Android app got back for a session
	// (POST /auth/oauth/exchange)
	ExchangeOAuthCode(w http.ResponseWriter, r *http.Request)
	// Where the provider sends the browser back
	// (GET /auth/oauth/{provider}/callback)
	OauthCallback(w http.ResponseWriter, r *http.Request, provider OAuthProviderId, params OauthCallbackParams)
	// Leave for the provider's sign-in page (opened in a browser)
	// (GET /auth/oauth/{provider}/start)
	StartOAuth(w http.ResponseWriter, r *http.Request, provider OAuthProviderId, params StartOAuthParams)
	// Email a password reset link
	// (POST /auth/password-reset)
	RequestPasswordReset(w http.ResponseWriter, r *http.Request)
	// Set a new password with the token from a reset email
	// (POST /auth/password-reset/confirm)
	ResetPassword(w http.ResponseWriter, r *http.Request)
	// Create an account with email and password (accounts mode)
	// (POST /auth/register)
	Register(w http.ResponseWriter, r *http.Request)
	// Confirm an email address with the token from a verification email
	// (POST /auth/verify-email)
	VerifyEmail(w http.ResponseWriter, r *http.Request)
	// The group, its members and their balances
	// (GET /g/{token})
	GetGroup(w http.ResponseWriter, r *http.Request, token Token)

	// (PATCH /g/{token})
	UpdateGroup(w http.ResponseWriter, r *http.Request, token Token, params UpdateGroupParams)
	// What happened in the group, newest first
	// (GET /g/{token}/activity)
	ListActivity(w http.ResponseWriter, r *http.Request, token Token, params ListActivityParams)
	// Net balances and the payments that settle them
	// (GET /g/{token}/balances)
	GetBalances(w http.ResponseWriter, r *http.Request, token Token)
	// Live notices that the group changed (server-sent events)
	// (GET /g/{token}/events)
	GroupEvents(w http.ResponseWriter, r *http.Request, token Token)
	// Expenses and payments, newest first
	// (GET /g/{token}/expenses)
	ListExpenses(w http.ResponseWriter, r *http.Request, token Token, params ListExpensesParams)

	// (POST /g/{token}/expenses)
	CreateExpense(w http.ResponseWriter, r *http.Request, token Token, params CreateExpenseParams)
	// Delete (restorable)
	// (DELETE /g/{token}/expenses/{expenseId})
	DeleteExpense(w http.ResponseWriter, r *http.Request, token Token, expenseId ExpenseId, params DeleteExpenseParams)
	// One expense, also when deleted
	// (GET /g/{token}/expenses/{expenseId})
	GetExpense(w http.ResponseWriter, r *http.Request, token Token, expenseId ExpenseId)

	// (PUT /g/{token}/expenses/{expenseId})
	UpdateExpense(w http.ResponseWriter, r *http.Request, token Token, expenseId ExpenseId, params UpdateExpenseParams)
	// Remove the photo of the receipt
	// (DELETE /g/{token}/expenses/{expenseId}/receipt)
	DeleteReceipt(w http.ResponseWriter, r *http.Request, token Token, expenseId ExpenseId, params DeleteReceiptParams)
	// The photo of the expense's receipt
	// (GET /g/{token}/expenses/{expenseId}/receipt)
	GetReceipt(w http.ResponseWriter, r *http.Request, token Token, expenseId ExpenseId)
	// Attach a photo of the receipt, replacing any earlier one
	// (PUT /g/{token}/expenses/{expenseId}/receipt)
	PutReceipt(w http.ResponseWriter, r *http.Request, token Token, expenseId ExpenseId, params PutReceiptParams)
	// Undo a delete
	// (POST /g/{token}/expenses/{expenseId}/restore)
	RestoreExpense(w http.ResponseWriter, r *http.Request, token Token, expenseId ExpenseId, params RestoreExpenseParams)
	// Every expense and payment of the group as a spreadsheet
	// (GET /g/{token}/export.csv)
	ExportCsv(w http.ResponseWriter, r *http.Request, token Token, params ExportCsvParams)
	// Email someone an invitation to the group (accounts mode)
	// (POST /g/{token}/invites)
	InviteToGroup(w http.ResponseWriter, r *http.Request, token Token)
	// What a signed-in person needs to decide to join (accounts mode)
	// (GET /g/{token}/join)
	GetJoinInfo(w http.ResponseWriter, r *http.Request, token Token)
	// Become a member, as a new member or by claiming a placeholder
	// (POST /g/{token}/join)
	JoinGroup(w http.ResponseWriter, r *http.Request, token Token)

	// (POST /g/{token}/members)
	AddMember(w http.ResponseWriter, r *http.Request, token Token, params AddMemberParams)
	// Mark a member as having left
	// (DELETE /g/{token}/members/{memberId})
	RemoveMember(w http.ResponseWriter, r *http.Request, token Token, memberId MemberId, params RemoveMemberParams)

	// (PATCH /g/{token}/members/{memberId})
	UpdateMember(w http.ResponseWriter, r *http.Request, token Token, memberId MemberId, params UpdateMemberParams)
	// Record that one member paid another
	// (POST /g/{token}/payments)
	CreatePayment(w http.ResponseWriter, r *http.Request, token Token, params CreatePaymentParams)
	// Replace the token; the old link stops working
	// (POST /g/{token}/reset-link)
	ResetGroupLink(w http.ResponseWriter, r *http.Request, token Token, params ResetGroupLinkParams)
	// What the group spent, by category, member and month
	// (GET /g/{token}/stats)
	GetStats(w http.ResponseWriter, r *http.Request, token Token, params GetStatsParams)
	// Create a group with its first members
	// (POST /groups)
	CreateGroup(w http.ResponseWriter, r *http.Request)
	// Create a group from another app's export
	// (POST /groups/import)
	ImportGroup(w http.ResponseWriter, r *http.Request)
	// Home screen cards for the groups a device knows
	// (POST /groups/summaries)
	GetGroupSummaries(w http.ResponseWriter, r *http.Request)
	// The signed-in account
	// (GET /me)
	GetMe(w http.ResponseWriter, r *http.Request)

	// (PATCH /me)
	UpdateMe(w http.ResponseWriter, r *http.Request)
	// Home screen cards for the groups the account is a member of
	// (GET /me/groups)
	GetMyGroups(w http.ResponseWriter, r *http.Request)
	// Set a new password; other sessions are signed out
	// (POST /me/password)
	ChangePassword(w http.ResponseWriter, r *http.Request)
	// Email a new verification link to the account's address
	// (POST /me/verify-email)
	SendVerifyEmail(w http.ResponseWriter, r *http.Request)
	// Stop sending this device notifications
	// (DELETE /push/devices/{device})
	RemovePushDevice(w http.ResponseWriter, r *http.Request, device string)
	// Send this device notifications about the groups it follows
	// (PUT /push/devices/{device})
	RegisterPushDevice(w http.ResponseWriter, r *http.Request, device string)
	// Mode and enabled features, read by the app on startup
	// (GET /server-info)
	GetServerInfo(w http.ResponseWriter, r *http.Request)
}

