// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Sign in as the administrator
	// (POST /admin/login)
	AdminLogin(ctx context.Context, request AdminLoginRequestObject) (AdminLoginResponseObject, error)
	// End this administrator session
	// (POST /admin/logout)
	AdminLogout(ctx context.Context, request AdminLogoutRequestObject) (AdminLogoutResponseObject, error)
	// Set a new administrator password; other admin sessions end
	// (POST /admin/password)
	ChangeAdminPassword(ctx context.Context, request ChangeAdminPasswordRequestObject) (ChangeAdminPasswordResponseObject, error)
	// The server settings an administrator can change
	// (GET /admin/settings)
	GetAdminSettings(ctx context.Context, request GetAdminSettingsRequestObject) (GetAdminSettingsResponseObject, error)
	// Change server settings
	// (PUT /admin/settings)
	UpdateAdminSettings(ctx context.Context, request UpdateAdminSettingsRequestObject) (UpdateAdminSettingsResponseObject, error)
	// Set the administrator password, once, on a new server
	// (POST /admin/setup)
	AdminSetup(ctx context.Context, request AdminSetupRequestObject) (AdminSetupResponseObject, error)
	// The invitation behind an invitation link
	// (GET /auth/invites/{inviteToken})
	GetInvite(ctx context.Context, request GetInviteRequestObject) (GetInviteResponseObject, error)
	// Sign in with email and password (accounts mode)
	// (POST /auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// End this session
	// (POST /auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// Trade the code the Android app got back for a session
	// (POST /auth/oauth/exchange)
	ExchangeOAuthCode(ctx context.Context, request ExchangeOAuthCodeRequestObject) (ExchangeOAuthCodeResponseObject, error)
	// Where the provider sends the browser back
	// (GET /auth/oauth/{provider}/callback)
	OauthCallback(ctx context.Context, request OauthCallbackRequestObject) (OauthCallbackResponseObject, error)
	// Leave for the provider's sign-in page (opened in a browser)
	// (GET /auth/oauth/{provider}/start)
	StartOAuth(ctx context.Context, request StartOAuthRequestObject) (StartOAuthResponseObject, error)
	// Email a password reset link
	// (POST /auth/password-reset)
	RequestPasswordReset(ctx context.Context, request RequestPasswordResetRequestObject) (RequestPasswordResetResponseObject, error)
	// Set a new password with the token from a reset email
	// (POST /auth/password-reset/confirm)
	ResetPassword(ctx context.Context, request ResetPasswordRequestObject) (ResetPasswordResponseObject, error)
	// Create an account with email and password (accounts mode)
	// (POST /auth/register)
	Register(ctx context.Context, request RegisterRequestObject) (RegisterResponseObject, error)
	// Confirm an email address with the token from a verification email
	// (POST /auth/verify-email)
	VerifyEmail(ctx context.Context, request VerifyEmailRequestObject) (VerifyEmailResponseObject, error)
	// The group, its members and their balances
	// (GET /g/{token})
	GetGroup(ctx context.Context, request GetGroupRequestObject) (GetGroupResponseObject, error)

	// (PATCH /g/{token})
	UpdateGroup(ctx context.Context, request UpdateGroupRequestObject) (UpdateGroupResponseObject, error)
	// What happened in the group, newest first
	// (GET /g/{token}/activity)
	ListActivity(ctx context.Context, request ListActivityRequestObject) (ListActivityResponseObject, error)
	// Net balances and the payments that settle them
	// (GET /g/{token}/balances)
	GetBalances(ctx context.Context, request GetBalancesRequestObject) (GetBalancesResponseObject, error)
	// Live notices that the group changed (server-sent events)
	// (GET /g/{token}/events)
	GroupEvents(ctx context.Context, request GroupEventsRequestObject) (GroupEventsResponseObject, error)
	// Expenses and payments, newest first
	// (GET /g/{token}/expenses)
	ListExpenses(ctx context.Context, request ListExpensesRequestObject) (ListExpensesResponseObject, error)

	// (POST /g/{token}/expenses)
	CreateExpense(ctx context.Context, request CreateExpenseRequestObject) (CreateExpenseResponseObject, error)
	// Delete (restorable)
	// (DELETE /g/{token}/expenses/{expenseId})
	DeleteExpense(ctx context.Context, request DeleteExpenseRequestObject) (DeleteExpenseResponseObject, error)
	// One expense, also when deleted
	// (GET /g/{token}/expenses/{expenseId})
	GetExpense(ctx context.Context, request GetExpenseRequestObject) (GetExpenseResponseObject, error)

	// (PUT /g/{token}/expenses/{expenseId})
	UpdateExpense(ctx context.Context, request UpdateExpenseRequestObject) (UpdateExpenseResponseObject, error)
	// Remove the photo of the receipt
	// (DELETE /g/{token}/expenses/{expenseId}/receipt)
	DeleteReceipt(ctx context.Context, request DeleteReceiptRequestObject) (DeleteReceiptResponseObject, error)
	// The photo of the expense's receipt
	// (GET /g/{token}/expenses/{expenseId}/receipt)
	GetReceipt(ctx context.Context, request GetReceiptRequestObject) (GetReceiptResponseObject, error)
	// Attach a photo of the receipt, replacing any earlier one
	// (PUT /g/{token}/expenses/{expenseId}/receipt)
	PutReceipt(ctx context.Context, request PutReceiptRequestObject) (PutReceiptResponseObject, error)
	// Undo a delete
	// (POST /g/{token}/expenses/{expenseId}/restore)
	RestoreExpense(ctx context.Context, request RestoreExpenseRequestObject) (RestoreExpenseResponseObject, error)
	// Every expense and payment of the group as a spreadsheet
	// (GET /g/{token}/export.csv)
	ExportCsv(ctx context.Context, request ExportCsvRequestObject) (ExportCsvResponseObject, error)
	// Email someone an invitation to the group (accounts mode)
	// (POST /g/{token}/invites)
	InviteToGroup(ctx context.Context, request InviteToGroupRequestObject) (InviteToGroupResponseObject, error)
	// What a signed-in person needs to decide to join (accounts mode)
	// (GET /g/{token}/join)
	GetJoinInfo(ctx context.Context, request GetJoinInfoRequestObject) (GetJoinInfoResponseObject, error)
	// Become a member, as a new member or by claiming a placeholder
	// (POST /g/{token}/join)
	JoinGroup(ctx context.Context, request JoinGroupRequestObject) (JoinGroupResponseObject, error)

	// (POST /g/{token}/members)
	AddMember(ctx context.Context, request AddMemberRequestObject) (AddMemberResponseObject, error)
	// Mark a member as having left
	// (DELETE /g/{token}/members/{memberId})
	RemoveMember(ctx context.Context, request RemoveMemberRequestObject) (RemoveMemberResponseObject, error)

	// (PATCH /g/{token}/members/{memberId})
	UpdateMember(ctx context.Context, request UpdateMemberRequestObject) (UpdateMemberResponseObject, error)
	// Record that one member paid another
	// (POST /g/{token}/payments)
	CreatePayment(ctx context.Context, request CreatePaymentRequestObject) (CreatePaymentResponseObject, error)
	// Replace the token; the old link stops working
	// (POST /g/{token}/reset-link)
	ResetGroupLink(ctx context.Context, request ResetGroupLinkRequestObject) (ResetGroupLinkResponseObject, error)
	// What the group spent, by category, member and month
	// (GET /g/{token}/stats)
	GetStats(ctx context.Context, request GetStatsRequestObject) (GetStatsResponseObject, error)
	// Create a group with its first members
	// (POST /groups)
	CreateGroup(ctx context.Context, request CreateGroupRequestObject) (CreateGroupResponseObject, error)
	// Create a group from another app's export
	// (POST /groups/import)
	ImportGroup(ctx context.Context, request ImportGroupRequestObject) (ImportGroupResponseObject, error)
	// Home screen cards for the groups a device knows
	// (POST /groups/summaries)
	GetGroupSummaries(ctx context.Context, request GetGroupSummariesRequestObject) (GetGroupSummariesResponseObject, error)
	// The signed-in account
	// (GET /me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)

	// (PATCH /me)
	UpdateMe(ctx context.Context, request UpdateMeRequestObject) (UpdateMeResponseObject, error)
	// Home screen cards for the groups the account is a member of
	// (GET /me/groups)
	GetMyGroups(ctx context.Context, request GetMyGroupsRequestObject) (GetMyGroupsResponseObject, error)
	// Set a new password; other sessions are signed out
	// (POST /me/password)
	ChangePassword(ctx context.Context, request ChangePasswordRequestObject) (ChangePasswordResponseObject, error)
	// Email a new verification link to the account's address
	// (POST /me/verify-email)
	SendVerifyEmail(ctx context.Context, request SendVerifyEmailRequestObject) (SendVerifyEmailResponseObject, error)
	// Stop sending this device notifications
	// (DELETE /push/devices/{device})
	RemovePushDevice(ctx context.Context, request RemovePushDeviceRequestObject) (RemovePushDeviceResponseObject, error)
	// Send this device notifications about the groups it follows
	// (PUT /push/devices/{device})
	RegisterPushDevice(ctx context.Context, request RegisterPushDeviceRequestObject) (RegisterPushDeviceResponseObject, error)
	// Mode and enabled features, read by the app on startup
	// (GET /server-info)
	GetServerInfo(ctx context.Context, request GetServerInfoRequestObject) (GetServerInfoResponseObject, error)
}

type StrictHandlerFunc = strictnethttp.StrictHTTPHandlerFunc
type StrictMiddlewareFunc = strictnethttp.StrictHTTPMiddlewareFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

